// ============================================================
// THĂM DÒ: đọc FULL nội dung bài báo qua proxy r.jina.ai
// (né chặn IP + tách văn bản sạch). Test 2 cách:
//  1) Lấy 1 link từ Google News rồi nhờ Jina đọc.
//  2) Nhờ Jina đọc thẳng 1 bài CafeF (xem có né được chặn không).
// ============================================================
const UA = 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0 Safari/537.36';

const results = [];

// --- B1: lấy 1 link bài từ Google News RSS ---
let gnLink = '';
try {
  const rss = await this.helpers.httpRequest({ method: 'GET', url: 'https://news.google.com/rss/search?q=' + encodeURIComponent('chứng khoán when:2d') + '&hl=vi&gl=VN&ceid=VN:vi', headers: { 'User-Agent': UA, 'Accept': '*/*' }, json: false, timeout: 20000 });
  const xml = typeof rss === 'string' ? rss : String(rss);
  const m = xml.match(/<item[\s\S]*?<link>([\s\S]*?)<\/link>/i);
  gnLink = m ? m[1].replace(/<!\[CDATA\[/g, '').replace(/\]\]>/g, '').trim() : '';
  results.push({ test: '0. Lấy link từ Google News', status: gnLink ? '✅' : '❌ không thấy link', value: gnLink.slice(0, 120) });
} catch (e) {
  results.push({ test: '0. Lấy link Google News', status: '❌ ' + (e.message || e), value: '' });
}

// --- B2: Jina đọc link Google News (tự follow redirect tới bài gốc) ---
if (gnLink) {
  try {
    const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://r.jina.ai/' + gnLink, headers: { 'User-Agent': UA, 'Accept': 'text/plain' }, json: false, timeout: 30000 });
    const txt = typeof res === 'string' ? res : String(res);
    results.push({ test: '1. Jina đọc link Google News', status: '✅ SỐNG (' + txt.length + ' ký tự)', value: txt.replace(/\s+/g, ' ').slice(0, 500) });
  } catch (e) {
    results.push({ test: '1. Jina đọc link Google News', status: '❌ ' + (e.message || e), value: '' });
  }
}

// --- B3: Jina đọc THẲNG 1 bài CafeF (site hay chặn IP) ---
try {
  const res = await this.helpers.httpRequest({ method: 'GET', url: 'https://r.jina.ai/https://cafef.vn/thi-truong-chung-khoan.chn', headers: { 'User-Agent': UA, 'Accept': 'text/plain' }, json: false, timeout: 30000 });
  const txt = typeof res === 'string' ? res : String(res);
  results.push({ test: '2. Jina đọc thẳng CafeF (test né chặn)', status: '✅ SỐNG (' + txt.length + ' ký tự)', value: txt.replace(/\s+/g, ' ').slice(0, 500) });
} catch (e) {
  results.push({ test: '2. Jina đọc thẳng CafeF', status: '❌ ' + (e.message || e), value: '' });
}

return results.map(r => ({ json: r }));
